<?php
// Auto Importer for NYAM Board and Advisors
error_reporting(E_ALL);
ini_set("display_errors", 1);

require_once __DIR__ . "/wp-load.php";

echo "<h2>Importing NYAM Board and Advisors...</h2><pre>";

$b64 = "";
$data = json_decode(base64_decode($b64), true);

if (!$data) {
  die("Error decoding JSON data.");
}

$total = 0;
foreach ($data as $group) {
  $cat = $group["category"];
  $term = term_exists($cat, "advisor_department");
  if (!$term) { $term = wp_insert_term($cat, "advisor_department"); }
  $tid = is_array($term) ? $term["term_id"] : (is_object($term) ? $term->term_id : (int)$term);
  echo "Department: " . htmlspecialchars($cat) . " (Term ID: " . $tid . ")
";
  $idx = 1;
  foreach ($group["members"] as $m) {
    $q = new WP_Query(["post_type" => "advisors", "title" => $m["name"], "posts_per_page" => 1]);
    $pid = $q->have_posts() ? $q->posts[0]->ID : 0;
    $args = ["post_title" => $m["name"], "post_content" => $m["bio"], "post_status" => "publish", "post_type" => "advisors"];
    if ($pid) { $args["ID"] = $pid; $pid = wp_update_post($args); echo "  [Updated] " . $m["name"] . "
"; }
    else { $pid = wp_insert_post($args); echo "  [Created] " . $m["name"] . "
"; }
    if (!is_wp_error($pid) && $pid) {
      wp_set_object_terms($pid, [(int)$tid], "advisor_department");
      update_post_meta($pid, "position", $m["position"]);
      update_post_meta($pid, "_position", "field_advisor_position");
      update_post_meta($pid, "bio", $m["bio"]);
      update_post_meta($pid, "_bio", "field_advisor_bio");
      update_post_meta($pid, "linkedin", $m["linkedin"]);
      update_post_meta($pid, "_linkedin", "field_advisor_linkedin");
      update_post_meta($pid, "order", $idx);
      update_post_meta($pid, "_order", "field_advisor_order");
      $total++; $idx++;
    }
  }
}
echo "
--------------------------------------------
";
echo "SUCCESS: All " . $total . " Advisors imported successfully!
";
echo "Go to WP Admin -> Advisors to see all of them!
";
echo "Please delete this import-advisors.php file now for security.
";
echo "</pre>";
